const BASE_URL = $env.SYNTARO_PUBLIC_URL || 'http://localhost:3000';
const HEALTH_ENDPOINTS = [
  '/health',
  '/health/queue',
  '/health/dependencies'
];

const results = await Promise.all(HEALTH_ENDPOINTS.map(async (endpoint) => {
  const url = `${BASE_URL}${endpoint}`;
  const start = Date.now();
  try {
    const response = await fetch(url, { signal: AbortSignal.timeout(10000) });
    const latency = Date.now() - start;
    let body = null;
    try { body = await response.json(); } catch {}
    return {
      endpoint,
      statusCode: response.status,
      latency,
      ok: response.ok,
      body
    };
  } catch (err) {
    return {
      endpoint,
      statusCode: 0,
      latency: Date.now() - start,
      ok: false,
      error: String(err)
    };
  }
}));

const allOk = results.every(r => r.ok);
const anyDown = results.some(r => !r.ok);

const previousStatus = $getWorkflowStaticData('global').lastOverallStatus;
const currentStatus = allOk ? 'healthy' : 'down';

let shouldAlert = false;
if (anyDown && previousStatus !== 'down') {
  shouldAlert = true;
} else if (allOk && previousStatus === 'down') {
  shouldAlert = true;
}

$getWorkflowStaticData('global').lastOverallStatus = currentStatus;

const failedEndpoints = results.filter(r => !r.ok);

return [{
  json: {
    allOk,
    currentStatus,
    previousStatus,
    shouldAlert,
    anyDown,
    results,
    failedEndpoints,
    timestamp: new Date().toISOString()
  }
}];

const item = $input.first().json;

const blocks = [
  {
    type: 'header',
    text: { type: 'plain_text', text: item.title || 'Health Check Alert' }
  },
  {
    type: 'section',
    text: { type: 'mrkdwn', text: item.text || 'No details' }
  },
  {
    type: 'context',
    elements: [
      { type: 'mrkdwn', text: 'Checked at ' + (item.timestamp || new Date().toISOString()) }
    ]
  }
];

// Parse details if present
let details = [];
try {
  if (item.details) {
    details = typeof item.details === 'string' ? JSON.parse(item.details) : item.details;
  }
} catch {}

if (details.length > 0) {
  blocks.push({
    type: 'divider'
  });
  const fields = details.map(d => ({
    type: 'mrkdwn',
    text: `*${d.endpoint}*\\n${d.ok !== false ? '✅ OK' : '❌ DOWN'}\\n${d.latency || d.status}`
  }));
  // Batch fields into groups of 2 per row (Slack limit is 10 per row)
  for (let i = 0; i < fields.length; i += 2) {
    blocks.push({
      type: 'section',
      fields: fields.slice(i, i + 2)
    });
  }
}

return [{
  json: {
    channel: item.channel || '#syntaro-alerts',
    attachments: JSON.stringify([{
      color: item.color || '#95A5A6',
      blocks: blocks
    }])
  }
}];
